import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import org.mockito.Mockito;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyToListWithoutException() {
        List<Property<?>> list = new ArrayList<>();
        Property<?> property = Mockito.mock(Property.class);
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(property);
        assertThat(builder.create(), is(list));
    }

    @Test
    public void addPropertyToListWithException() {
        List<Property<?>> list = new ArrayList<>();
        PropertyListBuilder builder = new PropertyListBuilder();
        try {
            builder.add(Mockito.mock(Property.class));
            assert false;
        } catch (ConfigMeException e) {
            assertThat(e.getMessage(), is("Failed to add property"));
        }
    }

    @Test
    public void createEmptyListWhenNoPropertiesAdded() {
        List<Property<?>> list = new ArrayList<>();
        PropertyListBuilder builder = new PropertyListBuilder();
        assertThat(builder.create(), is(list));
    }

    @Test
    public void getRootEntriesReturnsMapWithoutKeyError() {
        Map<String, Object> map = new LinkedHashMap<>();
        Mockito.when(PropertyListBuilder.getRootEntries()).thenReturn(map);
        PropertyListBuilder builder = new PropertyListBuilder();
        try {
            builder.create();
            assert false;
        } catch (NullPointerException e) {
            assertThat(e.getMessage(), is("No root entries available"));
        }
    }

    @Test
    public void getRootEntriesReturnsMapWithPropertiesCountMatchingAddMethod() {
        Map<String, Object> map = new LinkedHashMap<>();
        Mockito.when(PropertyListBuilder.getRootEntries()).thenReturn(map);
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(Mockito.mock(Property.class));
        builder.add(Mockito.mock(Property.class));
        assertThat(((Map) builder.create().get(0)), is(null)); // test properties are not present in the output
    }

}
